const cardboard=[];for(let i=0;i<3;i++){const b=box(1.4,.2,1.8,0xc6a47e,-5+i*1.4,.5,27);cardboard.push(b);interact(b,`Kadbod ${i+1}`,4,0,()=>{if(state.inventory.includes('kadbod'+i))return toast('Kadbod ini sudah dikumpul.');state.inventory.push('kadbod'+i);b.visible=false;save();toast(`Kadbod dikumpul: ${state.inventory.filter(x=>x.startsWith('kadbod')).length}/3`);if(cardboard.every((_,j)=>state.inventory.includes('kadbod'+j)))complete(4,0)})}const glue=cylinder(.4,1.3,0xf5f5fa,5,.8,27);cylinder(.22,.3,0xe995b7,5,1.6,27);interact(glue,'Ambil gam',4,1,()=>{if(!has(4,0))return toast('Kumpulkan tiga keping kadbod dahulu.');state.inventory.push('gam');glue.visible=false;complete(4,1);save()});const calculator=box(1.4,.4,1.8,0x738bad,0,.5,24);interact(calculator,'Semak kos',4,2,()=>{if(!has(4,1))return toast('Lengkapkan pengumpulan kadbod dan gam dahulu.');open(`<span class="eyebrow">MEJA PERANCANGAN</span><h2>Bajet kamu: RM10</h2><p>3 keping kadbod × RM2 + 1 bekas gam × RM2.</p><label for="cost">Berapakah jumlah kos (RM)?</label><input id="cost" type="number" min="0" step=".01" style="width:100%;padding:15px;margin-top:12px"><div id="costfeedback"></div><div class="actions"><button class="primary" onclick="window.rq.cost()">Semak pengiraan</button></div>`)});
