product=new T.Group();product.position.set(-25,.25,14);scene.add(product);function buildProduct(){product.clear();const d=state.design;cup(0,0,0,d.base/5,d.height/5,[0xe998ba,0xc4a37e,0xa6cbe4][d.material],product);product.rotation.z=0}buildProduct();const buildStation=box(2,.6,2,0xb596d2,-30,.5,18);interact(buildStation,'Bina produk',5,0,()=>builder());const testStation=box(2,.6,2,0x8fc4b5,-20,.5,18);interact(testStation,'Uji produk',5,1,()=>{if(!has(5,0))return toast('Bina produk di stesen ungu dahulu.');testProduct()});const finalTeacher=character(-25,8,0xb697df,true);interact(finalTeacher,'Bentang hasil',5,2,()=>{if(!has(5,1)||!state.testPassed)return toast('Produk semasa mesti lulus ujian sebelum pembentangan.');choice('Pilih penerangan yang menggunakan bukti pengembaraan kamu.',['Produk ini cantik, itu sahaja','Bekas asal tumbang; tapak dibaiki, bahan dipilih mengikut bajet, ujian 12 pensel berjaya','Saya tidak perlu menguji produk'],1,()=>{complete(5,2);setTimeout(journal,500)},'Terangkan masalah, pembaikan dan hasil ujian.')});
function choice(title,answers,correct,callback,hint){open(`<span class="eyebrow">BUKTI → KEPUTUSAN</span><h2>${title}</h2>${answers.map((s,i)=>`<button class="choice" data-answer="${i}">${esc(s)}</button>`).join('')}<div id="choicefeedback" aria-live="polite"></div><div class="actions"><button id="hintchoice">💡 Petunjuk</button></div>`);let h=0;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{state.attempts++;recordAnswer(title.startsWith('Pilih idea')?'idea':title.startsWith('Keputusan manakah')?'prototype':'presentation',+b.dataset.answer);save();if(+b.dataset.answer===correct){callback();$('#choicefeedback').innerHTML='<div class="feedback good">✓ Keputusan disokong bukti. Kamu boleh meneruskan pengembaraan.</div>';document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);$('#hintchoice').textContent='Teruskan →';$('#hintchoice').onclick=close}else $('#choicefeedback').innerHTML=`<div class="feedback">OOPS! ${hint} Pilih semula; mata penuh masih boleh diperoleh.</div>`});$('#hintchoice').onclick=()=>{h=Math.min(h+1,3);state.hints++;save();$('#choicefeedback').innerHTML=`<div class="note">Petunjuk ${h}/3: ${h===1?'Perhatikan bukti daripada objek dan pengguna.':h===2?esc(hint):'Contoh: kerusi yang bergoyang perlu dibaiki pada kaki atau tapaknya. Hiasan tidak menyelesaikan punca. Cuba gunakan prinsip yang sama dalam kes ini.'}<br><small>Petunjuk berstruktur, bukan AI langsung.</small></div>`}}
function builder(){open(`<span class="eyebrow">BENGKEL PEMBINAAN 3D</span><h2>Reka bekas kamu</h2><p>Ubah ciri produk. Objek di arena akan berubah sebaik tetapan disimpan. Sasaran: stabil dengan 12 pensel dan kos ≤ RM10.</p><label>Lebar tapak: <b id="basevalue">${state.design.base}</b> cm</label><input id="baseinput" type="range" min="4" max="16" value="${state.design.base}"><label>Tinggi: <b id="heightvalue">${state.design.height}</b> cm</label><input id="heightinput" type="range" min="8" max="24" value="${state.design.height}"><label for="matinput">Bahan</label><select id="matinput"><option value="0">Kadbod tebal — RM6</option><option value="1">Kayu ringan — RM9</option><option value="2">Kertas nipis — RM3</option></select><div class="note">Gam RM2. Tapak melebihi 10 cm memerlukan tambahan RM1.</div><div class="actions"><button class="primary" id="buildsave">Simpan & bina produk</button></div>`);$('#matinput').value=state.design.material;$('#baseinput').oninput=e=>$('#basevalue').textContent=e.target.value;$('#heightinput').oninput=e=>$('#heightvalue').textContent=e.target.value;$('#buildsave').onclick=()=>{state.design={base:+$('#baseinput').value,height:+$('#heightinput').value,material:+$('#matinput').value};state.testPassed=false;buildProduct();complete(5,0);save();close();toast('Produk 3D dibina! Pergi ke stesen hijau untuk mengujinya.')}}
function testProduct(){const d=state.design,cost=[6,9,3][d.material]+2+(d.base>10?1:0),stable=d.base>=d.height/2,strong=d.material!==2,pass=stable&&strong&&cost<=10;state.attempts++;const before=state.lastTest;state.lastTest={pass,cost,base:d.base,height:d.height};state.testPassed=pass;recordAnswer('product',{...d});if(!pass)audio.play('wrong');save();if(!stable){animated.push({type:'tip',mesh:product,time:0})}else product.rotation.z=0;open(`<span class="eyebrow">UJIAN PRODUK · 12 PENSEL</span><h2>${pass?'Produk kamu lulus!':'OOPS! Cuba reka semula.'}</h2><div class="feedback ${pass?'good':''}">${stable?'✓ Stabil':'✗ Tumbang: tapak terlalu sempit berbanding tinggi'}<br>${strong?'✓ Bahan cukup kukuh':'✗ Kertas nipis tidak menampung muatan'}<br>${cost<=10?'✓':'✗'} Kos RM${cost}.00 / RM10.00</div>${before?`<p>Ujian sebelumnya: ${before.pass?'lulus':'belum lulus'}, tapak ${before.base} cm, tinggi ${before.height} cm, kos RM${before.cost}. Ujian kini: ${pass?'lulus':'belum lulus'}.</p>`:''}<p>${pass?'Bentangkan hasil kepada Cikgu Reka di hadapan arena.':'Lebarkan tapak atau rendahkan badan. Semak bahan dan kos, kemudian jalankan ujian semula.'}</p><div class="note">Model pembelajaran: stabil jika tapak ≥ separuh tinggi. Bahan nipis gagal ujian muatan. Ini simulasi berasaskan peraturan, bukan fizik sebenar.</div><div class="actions"><button class="primary" id="testnext">${pass?'Simpan bukti ujian':'Baiki reka bentuk'}</button><button onclick="window.rq.close()">Lihat produk</button></div>`);if(pass)complete(5,1);$('#testnext').onclick=pass?close:builder}
function map(){if(bridge?.active)bridge.exit();open(`<span class="eyebrow">PETA DUNIA REKAQUEST</span><h2>Enam kawasan. Satu pengembaraan.</h2><p>Semua kawasan boleh diterokai dengan berjalan. Misi dibuka mengikut kemajuan. Pilih kawasan terbuka untuk perjalanan pantas.</p><div class="mapgrid">${missions.map((m,i)=>`<button data-teleport="${i}" ${unlocked(i)?'':'disabled'}>${m.icon} ${i+1}. ${m.name}<small>${finished(i)?'✓ Selesai':unlocked(i)?`${state.tasks[i].length}/${m.steps.length} cabaran`:'🔒 Lengkapkan misi sebelumnya'}</small></button>`).join('')}</div><div class="actions"><button id="square">⌂ Kembali ke dataran</button></div>`);document.querySelectorAll('[data-teleport]').forEach(b=>b.onclick=()=>{const m=missions[+b.dataset.teleport];autoWalk=false;player.position.set(m.x-3,0,m.z+1);vy=0;close();toast('Tiba di '+m.name)});$('#square').onclick=()=>{player.position.set(0,0,10);vy=0;close()}}
function journal(){open(`<span class="eyebrow">JURNAL PENGEMBARAAN</span><h2>${esc(state.name)} · Pereka Muda</h2><div class="statrow"><div><b>${score()}</b>MP / 300</div><div><b>${missions.filter((_,i)=>finished(i)).length}/6</b>Misi selesai</div></div><div class="badges">${missions.map((m,i)=>`<div class="badge ${finished(i)?'won':''}">${m.icon} <b>${m.badge}</b><p>${m.steps.map((s,j)=>`${has(i,j)?'✓':'○'} ${s}`).join('<br>')}</p></div>`).join('')}</div>${finished(5)?'<div class="feedback good">🏆 Tahniah! Semua bukti pengembaraan lengkap. Kamu telah menyiasat, merancang, membina dan menambah baik produk.</div>':''}<p class="small">Urutan misi ialah cadangan aktiviti dan belum disahkan dengan buku teks. Produk fizikal dan lakaran bebas masih memerlukan pentaksiran guru.</p><section class="note"><b>Misi 1 · Bukti pencapaian</b>${missions[0].steps.map((name,i)=>{const r=m1.record(i);return `<p>${esc(name)}: ${has(0,i)?10:0}/10 MP · ${r.attempts} percubaan · ${r.hints} petunjuk</p>`}).join('')}</section><div class="actions"><button class="primary" id="exportjournal">Muat turun jurnal</button><button onclick="window.rq.check()">Semak kefahaman RBT →</button></div><p class="small">Semakan situasi baharu dinilai berasingan daripada MP. Status simpanan rekod guru dipaparkan di atas skrin.</p>`);$('#exportjournal').onclick=()=>{const rows=[['Nama','Misi','Tugasan','Status','Markah terbaik','Percubaan','Petunjuk'],...missions.flatMap((m,i)=>m.steps.map((s,j)=>[state.name,m.name,s,has(i,j)?'Selesai':'Belum selesai',has(i,j)?10:0,i===0?m1.record(j).attempts:'',i===0?m1.record(j).hints:'']))];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='Jurnal-REKAQUEST-3D.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
function help(){if(!finished(0))return missionOneIntro();open(`<span class="eyebrow">CARA BERMAIN</span><h2>Kamu yang mengawal pengembaraan.</h2><p><b>W A S D / kekunci anak panah</b> — berjalan.<br><b>Space</b> — melompat.<br><b>E</b> — berinteraksi dengan objek berdekatan.<br><b>Seret pada dunia</b> — putar kamera. Roda tetikus — zum.<br><b>Peta dunia</b> — perjalanan pantas ke kawasan terbuka.</p><div class="note">Pada tablet/telefon, gunakan butang arah, lompat dan E pada skrin. Klik objek hanya apabila watak berada dekat dengannya.</div><p>Lengkapkan 5 cabaran Misi 1 dan aktiviti kawasan seterusnya untuk memperoleh lencana dan membuka misi seterusnya. Kesilapan boleh dibaiki tanpa penalti mata.</p><div class="actions"><button class="primary" onclick="window.rq.close()">Jom bermain</button></div>`)}
window.rq={close,map,check:()=>openChecks({state,open}),follow:followGuide,intro:missionOneIntro,sketchAdd:addSketch,cost(){const v=$('#cost').value;if(v==='')return toast('Masukkan jumlah dahulu.');state.attempts++;recordAnswer('cost',+v);if(+v===8){complete(4,2);$('#costfeedback').innerHTML='<div class="feedback good">✓ RM6 + RM2 = RM8. Baki RM2. Bahan mencukupi dan dalam bajet!</div>'}else $('#costfeedback').innerHTML='<div class="feedback">Kira 3 × RM2 dahulu, kemudian tambah harga satu bekas gam. Cuba semula.</div>';save()}};$('#mapbtn').onclick=map;$('#journalbtn').onclick=journal;$('#helpbtn').onclick=help;$('#checkbtn').onclick=()=>openChecks({state,open});bindRewards({request:rewardRequest,getState:()=>state,open,close,flush:flushCloud});$('#collapsemission').onclick=()=>{const compact=$('#mission').classList.toggle('compact');$('#collapsemission').textContent=compact?'+':'−';$('#collapsemission').setAttribute('aria-label',compact?'Paparkan panel misi':'Ringkaskan panel misi');};

