const trail=Array.from({length:14},()=>box(.28,.07,.44,0xffdc77,0,.36,0));let guideKey=-2;
function nextTask(){return [0,1,2,3,4].find(i=>!has(0,i))??5}
function rawGuideTarget(){const k=nextTask();if(k===0){return {cup:{x:-29,z:-26,approachX:-28,approachZ:-23.5,title:'1 · Jejak Petunjuk: bekas tumbang',text:'Periksa bekas di atas meja dan tentukan sama ada reka bentuk perlu ditambah baik.'},books:{x:-23,z:-19,approachX:-25,approachZ:-21,title:'1 · Jejak Petunjuk: buku berselerak',text:'Periksa buku. Bezakan masalah produk daripada keadaan yang hanya perlu dikemas.'},broken:{x:-30,z:-19,approachX:-28,approachZ:-21.5,title:'1 · Jejak Petunjuk: bekas retak',text:'Periksa retakan. Tentukan kesannya kepada penggunaan dan ketahanan.'}}[m1.nextObject()||'cup']}return {1:{x:-25,z:-30,approachX:-25,approachZ:-27,title:'2 · Detektif Punca dan Kesan',text:'Masuk Obby RBT. Pasang blok punca atau kesan untuk membina jambatan, kemudian lompat ke platform seterusnya.'},2:{x:-20,z:-23,approachX:-22,approachZ:-23,title:'3 · Bilik Aduan Pengguna',text:'Temui tiga pengguna. Baca semua aduan dan pilih bukti paling relevan berserta alasan.'},3:{x:-17,z:-29,approachX:-19,approachZ:-27,title:'4 · Susun Siasatan',text:'Susun empat kad tindakan mengikut urutan siasatan. Seret kad atau gunakan butang anak panah.'},4:{x:-17,z:-18,approachX:-19,approachZ:-20,title:'5 · Masalah atau Sekadar Hiasan?',text:'Kelaskan lima situasi kepada fungsi, keselamatan, ketahanan atau estetik. Ada kad memerlukan dua kategori.'}}[k]}
function guideTarget(){const g=rawGuideTarget();return g?{...g,x:g.x*WORLD_SCALE,z:g.z*WORLD_SCALE,approachX:g.approachX*WORLD_SCALE,approachZ:g.approachZ*WORLD_SCALE}:null}
function guidedInteractive(){const g=guideTarget();return g?interactives.find(o=>o.m===0&&o.t===nextTask()&&Math.abs(o.pos.x-g.x)<.5&&Math.abs(o.pos.z-g.z)<.5):null}
function followGuide(){close();const g=guideTarget();if(!g)return;autoWalk=true;toast('Watak mengikut jejak kuning. Tekan arah untuk mengawal sendiri.');}
function updateGuide(time){const g=active?guideTarget():null;$('#guide').hidden=!g||modal;arrow.visible=halo.visible=!!g;if(!g){trail.forEach(x=>x.visible=false);return}arrow.position.set(g.x,5.4+Math.sin(time*3)*.2,g.z);halo.position.set(g.x,.36,g.z);halo.rotation.y=time*.2;const dx=g.approachX-player.position.x,dz=g.approachZ-player.position.z,distance=Math.hypot(dx,dz);trail.forEach((p,i)=>{p.visible=distance>1;const t=(i+1)/15;p.position.set(player.position.x+dx*t,.38,player.position.z+dz*t);p.rotation.y=Math.atan2(dx,dz)});const k=nextTask()+'-'+(m1.nextObject()||'');if(k!==guideKey){guideKey=k;$('#guidetitle').textContent=g.title;$('#guidetext').textContent=g.text}$('#followbtn').textContent=autoWalk?'Mengikut laluan…':Math.hypot(player.position.x-g.x,player.position.z-g.z)<5.5?'Tekan E: buka aktiviti':'Tunjukkan jalan →'}
$('#followbtn').onclick=()=>{const g=guideTarget();if(g&&Math.hypot(g.x-player.position.x,g.z-player.position.z)<5.5)interactNearest();else followGuide()};
function missionOneIntro(){autoWalk=false;open(`<span class="eyebrow">MISI 1 · LIMA CABARAN · 50 MP</span><h2>Jadi detektif reka bentuk!</h2><p>Di kelas ada bekas pensel tumbang, buku berselerak dan bekas yang retak. Siasat masalah melalui lima aktiviti yang berbeza.</p><div class="evidence">① <b>Jejak Petunjuk:</b> periksa dan nilai tiga objek.<br>② <b>Detektif Punca dan Kesan:</b> padankan kad.<br>③ <b>Bilik Aduan Pengguna:</b> bandingkan tiga aduan.<br>④ <b>Susun Siasatan:</b> susun empat langkah.<br>⑤ <b>Masalah atau Sekadar Hiasan?:</b> kelaskan kad.</div><p>Setiap cabaran memberi <b>10 MP selepas kriteria dipenuhi</b>. Membaca dialog sahaja tidak memberikan mata.</p><div class="note">Ikut anak panah dan jejak kuning. Tekan <b>E</b> atau klik objek apabila dekat. Gunakan <b>Tunjukkan jalan</b> jika perlu.${state.m1Updated?'<br>Misi 1 telah dikemas kini. Rekod lama disimpan berasingan; cabaran baharu perlu diselesaikan. Rekod misi lain dikekalkan.':''}</div><div class="actions"><button class="primary" id="enterclass">Masuk ke kelas & mula siasatan →</button></div>`);$('#enterclass').onclick=()=>{player.position.set(-27*WORLD_SCALE,0,-17*WORLD_SCALE);vy=0;camera.position.set(-17*WORLD_SCALE,19,-5*WORLD_SCALE);yaw=.6;close();updateHUD();toast('Cabaran 1: periksa dan nilai ketiga-tiga objek dalam kelas.')}}
function missionOneDone(){autoWalk=false;open(`<span class="eyebrow">✓ MISI 1 SELESAI · 50/50 MP</span><h2>Lima cabaran siasatan berjaya!</h2><div class="evidence">✓ Mengenal pasti masalah pada objek — 10 MP<br>✓ Membezakan punca dan kesan — 10 MP<br>✓ Memilih aduan dan alasan berasaskan bukti — 10 MP<br>✓ Menyusun langkah siasatan — 10 MP<br>✓ Mengelaskan fungsi, keselamatan, ketahanan dan estetik — 10 MP</div><p>Kesimpulan kes Aina: bekas bertapak sempit mudah tumbang, menyebabkan pensel berselerak. Pengguna memerlukan bekas yang stabil dan selamat. Retakan pula menunjukkan masalah ketahanan.</p><div class="actions"><button class="primary" id="nextmission">Terus ke Makmal Idea →</button><button onclick="window.rq.close()">Teroka kelas semula</button></div>`);$('#nextmission').onclick=()=>{player.position.set(-3*WORLD_SCALE,0,-31*WORLD_SCALE);vy=0;close();toast('Misi 2: periksa idea A dan B, kemudian uji kedua-duanya.')}}
