const ray=new T.Raycaster(),mouse=new T.Vector2();renderer.domElement.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,lastX:e.clientX,moved:0};renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.lastX;drag.moved+=Math.abs(dx)+Math.abs(e.clientY-drag.y)*.01;yaw-=dx*.008;drag.lastX=e.clientX});renderer.domElement.addEventListener('pointerup',e=>{if(drag&&drag.moved<8&&active&&!modal){mouse.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);ray.setFromCamera(mouse,camera);const hit=ray.intersectObjects(interactives.map(o=>o.mesh),true)[0];if(hit){const o=interactives.find(o=>{let p=hit.object;while(p){if(p===o.mesh)return true;p=p.parent}return false});if(o){if(Math.hypot(player.position.x-o.pos.x,player.position.z-o.pos.z)<5.5)trigger(o);else toast('Rapatkan watak dengan objek untuk berinteraksi.')}}}drag=null});renderer.domElement.addEventListener('wheel',e=>{camDistance=T.MathUtils.clamp(camDistance+e.deltaY*.015,12,38)},{passive:true});
