const clock=new T.Clock(),targetCam=new T.Vector3();function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04),time=clock.elapsedTime;if(active&&!modal&&!bridge?.active){let f=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0),r=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);if(autoWalk){const goal=guideTarget();if(goal){const gx=goal.approachX-player.position.x,gz=goal.approachZ-player.position.z;if(Math.hypot(player.position.x-goal.x,player.position.z-goal.z)>4.3){f=-Math.sin(yaw)*gx-Math.cos(yaw)*gz;r=Math.cos(yaw)*gx-Math.sin(yaw)*gz}else{autoWalk=false;toast('Sudah dekat! Tekan E atau klik objek untuk menyiasat.')}}else autoWalk=false}const len=Math.hypot(f,r);if(len){f/=len;r/=len;const dx=(-Math.sin(yaw)*f+Math.cos(yaw)*r)*(keys.shift?13:8)*dt,dz=(-Math.cos(yaw)*f-Math.sin(yaw)*r)*(keys.shift?13:8)*dt;const nx=player.position.x+dx,nz=player.position.z+dz;const blocked=(x,z)=>colliders.some(o=>Math.abs(x-o.x)<o.w/2+.45&&Math.abs(z-o.z)<o.d/2+.45)&&player.position.y<1.8;if(!blocked(nx,player.position.z))player.position.x=T.MathUtils.clamp(nx,-96,96);if(!blocked(player.position.x,nz))player.position.z=T.MathUtils.clamp(nz,-91,86);player.rotation.y=Math.atan2(dx,dz);walkTime+=dt*12;if(player.position.y<.01&&time-lastStepSound>.34){audio.play('step');lastStepSound=time;}armL.rotation.x=Math.sin(walkTime)*.65;armR.rotation.x=-Math.sin(walkTime)*.65;legL.rotation.x=-Math.sin(walkTime)*.65;legR.rotation.x=Math.sin(walkTime)*.65}else{armL.rotation.x*=.8;armR.rotation.x*=.8;legL.rotation.x*=.8;legR.rotation.x*=.8}vy-=22*dt;player.position.y=Math.max(0,player.position.y+vy*dt);if(player.position.y===0){if(vy<-3)audio.play('land');vy=0;}}if(bridge?.active)bridge.tick(dt,time,active&&!modal,keys,yaw);let closest=null,dist=5.5;for(const o of interactives){if(!o.mesh.visible)continue;const d=Math.hypot(player.position.x-o.pos.x,player.position.z-o.pos.z);if(d<dist){dist=d;closest=o}o.marker.position.y=4.2+Math.sin(time*2+o.pos.x)*.12;o.marker.visible=(o.m!==0||o.t<=nextTask())&&d<15;}const priority=guideTarget();if(active&&priority){const po=guidedInteractive();if(po&&Math.hypot(player.position.x-po.pos.x,player.position.z-po.pos.z)<5.5)closest=po}near=closest;updateGuide(time);explorerTick(time);if(active&&!modal&&near&&!bridge?.active){$('#prompt').hidden=false;$('#prompt').innerHTML=`<b>E</b> ${esc(near.label)} ${near.m>=0&&!unlocked(near.m)?'🔒':''}`}else $('#prompt').hidden=true;if(bridge?.active)$('#area').textContent='OBBY • JAMBATAN BUKTI';const a=bridge?.active?-2:missions.findIndex(m=>Math.hypot(player.position.x-m.x,player.position.z-m.z)<20);if(a!==area){area=a;$('#area').textContent=a===-2?'OBBY • JAMBATAN BUKTI':a<0?'DATARAN REKAQUEST':missions[a].name.toUpperCase()}for(let i=animated.length-1;i>=0;i--){const a=animated[i];if(a.type==='tip'){a.time+=dt;a.mesh.rotation.z=Math.min(a.time*2,1.15);if(a.time>1)animated.splice(i,1)}else{a.life-=dt;a.mesh.position.y-=dt*2;a.mesh.position.x+=a.vx*dt;a.mesh.position.z+=a.vz*dt;a.mesh.rotation.x+=dt*4;if(a.life<=0){scene.remove(a.mesh);animated.splice(i,1)}}}targetCam.set(player.position.x+Math.sin(yaw)*camDistance,player.position.y+camDistance*.62+3,player.position.z+Math.cos(yaw)*camDistance);camera.position.lerp(targetCam,.09);camera.lookAt(player.position.x,player.position.y+1.8,player.position.z);renderer.render(scene,camera)}camera.position.set(15,18,26);addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});$('#loading').style.display='none';animate();
